def most_frequent_word(words):
    counts = {}
    order = []
    for word in words:
        if word not in counts:
            counts[word] = 0
            order.append(word)
        counts[word] += 1
    best = ""
    best_count = 0
    for word in order:
        if counts[word] > best_count:
            best = word
            best_count = counts[word]
    return best
